// Verify Standards finding: is (100.01,5) === 90.009 exact, or lucky?
const impl=(t,p)=>{const e=t>100?Math.max(p,10):p;return t*(1-e/100);};
const got=impl(100.01,5);
console.log("strictEqual holds today:", got===90.009);
console.log("got      :", got.toPrecision(20));
console.log("literal  :", (90.009).toPrecision(20));
// ulp margin
const ulp=Math.pow(2,-46)*Math.pow(2,Math.floor(Math.log2(90.009)));
console.log("ulp near 90.009 ~", ulp);
// Does an algebraically-equivalent rewrite break it?
console.log("t*0.9 form      :", (100.01*0.9)===90.009);
console.log("t-t*0.1 form    :", (100.01-100.01*0.1)===90.009);
console.log("t*(100-10)/100  :", (100.01*(100-10)/100)===90.009);
console.log("t*90/100        :", (100.01*90/100)===90.009);
'

