  const t=c/100, expected=Number((t*0.9).toPrecision(3)); // hand-written decimal
  if(impl(t,5)!==expected){fails++; if(!ex)ex=[t,impl(t,5),expected];}
}
console.log("fragile cent-values in 100.01..102.00:",fails,"/200");
console.log("first counterexample:",ex);
